using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class VillageMelodyChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var s=JsonUtility.FromJson<SliceState>("{\"version\":1,\"seconds\":180}");Check(s.Valid(),"Legacy save rejected");var memory=new VillageMelodyMemory();Check(memory.Valid()&&!memory.Reinforce(0,true)&&memory.Bias(0)==0,"Unknown motif trained");for(int m=0;m<4;m++){var notes=Enumerable.Range(0,4).Select(i=>VillageMelodies.Note(m,i)).ToArray();Check(notes.Contains(0)&&notes.Contains(1),"Motif lacks two tones");}memory.Record(2);memory.Reinforce(2,true);Check(memory.echoes[2]==1&&memory.Bias(2)>0&&memory.Bias(1)==0,"Phrase-specific reinforcement failed");memory.Reinforce(2,false);memory.Reinforce(2,false);Check(memory.Bias(2)<0&&memory.Valid(),"Discouragement failed");s.WorldPlay.villageMelodies=memory;Check(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(s)).Valid(),"Melody save invalid");memory.preference[0]=float.NaN;Check(!s.Valid(),"Nonfinite melody accepted");var forged=new SliceState();forged.Hybrid.receipt=new ActionReceipt{villageMelody=true,rhythmGame=true,melodyMotif=1,action=CreatureAction.PlayWithToy,partner="villager-0"};Check(!forged.Valid(),"Unlearned typed lesson accepted");forged.WorldPlay.villageMelodies=new VillageMelodyMemory{echoes=null};Check(!forged.Valid(),"Malformed typed-lesson save accepted");Debug.Log("BWVR_VILLAGE_MELODY_MODEL_PASS: legacy saves, authored two-tone motifs, unknown/positive/negative preference separation, serialization, bounds and typed-lesson provenance");}
 public static void VerifyRuntime(bool occluded=false){GameObject wall=null;string learnedSave=null;int motif=-1;bool checkedCompletion=false;var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();
  try{SharedActivitiesChecks.VerifyWithCapture((music,host,god)=>{if(!occluded)return;var unit=god.GetComponent<IslandNavigator>().world.Scale;var from=god.transform.position+Vector3.up*unit*10;var end=music.GetComponent<Collider>().bounds.center;wall=new GameObject("Melody occlusion QA wall");wall.transform.position=Vector3.Lerp(from,end,.5f);wall.AddComponent<BoxCollider>().size=new Vector3(8,4,8)*unit;Physics.SyncTransforms();},(music,host,god)=>{
   checkedCompletion=true;var state=god.Season;Check(music.PerformedNotes.Length==8&&music.VillagerPerformed.SequenceEqual(new[]{true,true,false,false,true,true,false,false}),"Native note sources changed");motif=host.MelodyChoice;for(int beat=0;beat<8;beat++)Check(music.PerformedNotes[beat]==VillageMelodies.Note(motif,beat/4*2+beat%2),"Creature did not echo the villager's call");Check((state.worldPlay.echo?.demonstrations??0)==0&&(state.worldPlay.echo?.games??0)==0,"Villager music credited to player echo system");
   if(occluded){Check(music.CompletedMelody<0&&state.worldPlay.villageMelodies==null&&!host.Memory.hasMelody&&!state.Hybrid.receipt.villageMelody,"Occluded calls taught a motif");UnityEngine.Object.DestroyImmediate(wall);wall=null;}else Check(music.CompletedMelody==motif&&state.worldPlay.villageMelodies.echoes[motif]==1&&host.Memory.hasMelody&&host.Memory.melodyEchoes==1&&state.Hybrid.receipt.villageMelody&&state.Hybrid.receipt.melodyMotif==motif&&state.Hybrid.receipt.partner==host.GetComponent<HybridTarget>().id,"Completed melody/source not remembered");
  },(music,host,god)=>{if(occluded)return;var memory=god.Season.worldPlay.villageMelodies;Check(memory.preference[motif]>.5f&&memory.echoes[motif]==1,"Native feedback did not reinforce melody exactly once");learnedSave=JsonUtility.ToJson(god.Season);});Check(checkedCompletion,"Native duet did not complete");
   if(!occluded){var field=typeof(QuestSlice).GetField("state",F);var original=(SliceState)field.GetValue(slice);var god=slice.GetComponentInChildren<CreatureHybrid>();try{god.Interrupt("Melody persistence QA");field.SetValue(slice,JsonUtility.FromJson<SliceState>(learnedSave));typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);var loaded=(SliceState)field.GetValue(slice);Check(loaded.Valid()&&loaded.worldPlay.villageMelodies.echoes[motif]==1&&loaded.worldPlay.villageMelodies.preference[motif]>.5f&&loaded.Social(0).hasMelody&&loaded.Social(0).melodyMotif==motif&&loaded.Social(0).melodyEchoes==1,"Native Save/Load lost melody or feedback");}finally{field.SetValue(slice,original);god.NewSeason();}}
   Debug.Log(occluded?"BWVR_VILLAGE_MELODY_OCCLUSION_PASS: native shared duet with a blocking collider after first pair, partial heard calls did not create motif memory or a motif teaching receipt; ordinary social play preserved":"BWVR_VILLAGE_MELODY_RUNTIME_PASS: native villager carry/present and utility acceptance, eight actual sourced motif taps/replies, completed host/creature memory, partner-specific typed feedback, no player demonstration credit, native Save/Load and existing pause/cancel/duplicate cleanup");
  }finally{if(wall!=null)UnityEngine.Object.DestroyImmediate(wall);}
 }
}
}
